import { Component } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { TYPE_GROUPS, readCssVar } from '../sg-tokens';

@Component({
  selector: 'sg-typography',
  imports: [TranslateModule],
  template: `
    <h1 class="sg-h">{{ 'sg.nav.typography' | translate }}</h1>
    <p class="sg-desc">{{ 'sg.typography.desc' | translate }}</p>

    @for (g of groups; track g.label) {
      <section class="sg-group">
        <h2 class="sg-group-h">{{ g.label }}</h2>
        <div class="rows">
          @for (t of g.items; track t.key) {
            <div class="row">
              <div class="specimen" [style]="styleFor(t.key)">{{ sample }}</div>
              <div class="meta">
                <span class="name">{{ t.label }}</span>
                <span class="spec">{{ spec(t.key) }}</span>
              </div>
            </div>
          }
        </div>
      </section>
    }
  `,
  styleUrls: ['../sg-page.css'],
  styles: [`
    .rows { display: flex; flex-direction: column; }
    .row {
      display: flex; align-items: baseline; gap: 24px;
      padding: 12px 0;
      border-bottom: 1px solid var(--border-soft);
    }
    .specimen {
      flex: 1; min-width: 0; color: var(--text-strong);
      font-family: var(--font-sans);
      white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    }
    .meta { flex-shrink: 0; width: 260px; display: flex; flex-direction: column; gap: 2px; text-align: right; }
    .name { font-size: var(--fs-13); font-weight: 500; color: var(--text-body); }
    .spec { font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; }
  `],
})
export class SgTypography {
  protected readonly groups = TYPE_GROUPS;
  protected readonly sample = 'Aa Bb Cc — Xin chào 0123';

  protected styleFor(key: string): Record<string, string> {
    const tr = readCssVar(`${key}-text-transform`) || 'none';
    return {
      'font-size': `var(${key}-font-size)`,
      'line-height': `var(${key}-line-height)`,
      'font-weight': `var(${key}-font-weight)`,
      'letter-spacing': `var(${key}-letter-spacing)`,
      'text-transform': tr,
    };
  }

  protected spec(key: string): string {
    return `${readCssVar(`${key}-font-size`)} / ${readCssVar(`${key}-line-height`)} · ${readCssVar(`${key}-font-weight`)}`;
  }
}
